import json
H=W=30
g=[[0]*W for _ in range(H)]
# 4x4 complete tile arrangement, tiles start at 1,8,15,22; final clipped tile row/column are color-4 top/left frame only.
centers=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
starts=[1,8,15,22]
for ri,r0 in enumerate(starts):
 for ci,c0 in enumerate(starts):
  for dr in range(5):
   for dc in range(5):
    r,c=r0+dr,c0+dc
    if r<30 and c<30:
     g[r][c]=4 if dr in (0,4) or dc in (0,4) else centers[ri][ci]
# clipped fifth row and column consist solely of top/left border color 4 where the original has it
for c0 in starts+[29]:
 for c in range(c0,min(c0+5,30)):
  if 29 < 30 and c<30: g[29][c]=4
for r0 in starts+[29]:
 for r in range(r0,min(r0+5,30)):
  if r<30: g[r][29]=4
# connect equal-colored tile markers along rows/columns, filling only intervening zero corridors
for ri in range(4):
 for a in range(4):
  for b in range(a+1,4):
   col=centers[ri][a]
   if centers[ri][b]==col:
    rr=starts[ri]+2
    for ci in range(a,b):
     for cc in range(starts[ci]+5, starts[ci+1]):
      g[rr][cc]=col
for ci in range(4):
 for a in range(4):
  for b in range(a+1,4):
   col=centers[a][ci]
   if centers[b][ci]==col:
    cc=starts[ci]+2
    for ri in range(a,b):
     for rr in range(starts[ri]+5, starts[ri+1]):
      g[rr][cc]=col
assert len(g)==30 and all(len(row)==30 for row in g)
print(json.dumps(g,separators=(',',':')))

